mod selective;
use std::time::Instant;
use typst_infra::fonts::font_info_from_bytes;
use typst_core::entities::font_book::{Coverage,FontInfo};
fn info(b:&[u8],i:u32,coverage:bool)->Option<FontInfo>{let mut x=font_info_from_bytes(b,i)?;if coverage{let f=ttf_parser::Face::parse(b,i).ok()?;let mut v=Vec::new();if let Some(c)=f.tables().cmap{for s in c.subtables{if s.is_unicode(){s.codepoints(|p|v.push(p));}}}x.coverage=Coverage::from_codepoints(v);}Some(x)}
fn main(){let t=Instant::now();let mut db=fontdb::Database::new();db.load_system_fonts();let discovery_ms=t.elapsed().as_secs_f64()*1000.;let faces:Vec<_>=db.faces().filter_map(|f|match &f.source{fontdb::Source::File(p)|fontdb::Source::SharedFile(p,_)=>Some((f.id,p.clone(),f.index)),_=>None}).collect();let mut samples=Vec::new();
 for iteration in 0..4{for mode in if iteration%2==0{[0,1,2,3]}else{[3,2,1,0]}{let selective=mode%2==1;let coverage=mode>=2;let t=Instant::now();let mut bytes=0;let mut values=Vec::new();for(id,p,i)in &faces{let x=if selective{let mut file=std::fs::File::open(p).unwrap();let size=file.metadata().unwrap().len();let(b,n)=selective::read(&mut file,size,*i,coverage).expect("supported face");bytes+=n;info(&b,0,coverage)}else{db.with_face_data(*id,|b,i|info(b,i,coverage)).flatten()};values.push(x);}let ms=t.elapsed().as_secs_f64()*1000.;for((id,_,_),x)in faces.iter().zip(&values){assert_eq!(x,&db.with_face_data(*id,|b,i|info(b,i,coverage)).flatten());}samples.push(serde_json::json!({"iteration":iteration,"mode":match mode{0=>"remap_metadata",1=>"selective_metadata",2=>"remap_with_coverage",_=>"selective_with_coverage"},"ms":ms,"read_bytes":bytes,"equal":true}));}}
 println!("{}",serde_json::json!({"discovery_ms":discovery_ms,"faces":faces.len(),"paths":faces.iter().map(|x|x.1.clone()).collect::<std::collections::BTreeSet<_>>(),"samples":samples}));}
#[cfg(test)] mod tests;
